/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones=['.','com','net','example.com','service.com','lab.net','tools.net','shop.example.com','api.service.com','research.lab.net','ci.tools.net','ai.research.lab.net','data.research.lab.net']
parents={1:0,2:0,3:1,4:1,5:2,6:2,7:3,8:4,9:5,10:6,11:9,12:9}
ips=[re.search(r'inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,15)]
for i,z in enumerate(zones):
 d=Path(f'pc{i+1}/etc/bind'); data=(d/('db.root' if i==0 else 'db.'+z)).read_text(); conf=(d/'named.conf').read_text()
 assert f'zone \"{z}\"' in conf and 'recursion no' in conf
 assert data.count(' IN SOA ')==1 and '@ IN NS ' in data
 for child,parent in parents.items():
  if parent==i:
   name=f'ns.{zones[child]}.'
   assert f'{zones[child]}. IN NS {name}' in data and f'{name} IN A {ips[child]}' in data
   childdata=Path(f'pc{child+1}/etc/bind/db.{zones[child]}').read_text()
   assert f'@ IN NS {name}' in childdata and f'{name} IN A {ips[child]}' in childdata
 for line in data.splitlines():
  if ' IN A ' in line: assert line.split()[-1] in ips
for i in range(16,21): assert f'nameserver {ips[13]}' in Path(f'pc{i}.startup').read_text()
for i in range(1,15): assert Path(f'pc{i}.startup').read_text().rstrip().endswith('systemctl restart named')
print('Static checks passed: 13 zones, 12 delegations, matching glue, server startup and five clients.')
PY
"

